scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_238'] || []

control 'CKV_AWS_238' do
  title 'Ensure that GuardDuty detector is enabled'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_guardduty_detector resources that actually exist, enumerated
    through the two-step (parent -> child) declarative API spec.
  DESC

  desc 'rationale', <<~RATIONALE
    A detector that exists but is suspended keeps its configuration and its
    findings history while analysing nothing, so the account looks monitored
    in an inventory and is not. This is the deployed state Terraform cannot
    show.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_guardduty_detector: enable is True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_guardduty_detector:

      resource "aws_guardduty_detector" "main" {
        enable                       = true
        finding_publishing_frequency = "FIFTEEN_MINUTES"

        datasources {
          s3_logs {
            enable = true
          }
          kubernetes {
            audit_logs {
              enable = true
            }
          }
          malware_protection {
            scan_ec2_instance_with_findings {
              ebs_volumes {
                enable = true
              }
            }
          }
        }
      }

    Out of band — aws_guardduty_detector:

      aws guardduty update-detector --detector-id <id> --enable

    Note (aws_guardduty_detector): A detector is per region. An account with a
    detector in one region and none in another is not covered in the second, and
    this control only sees the regions in scan_regions.
  FIX

  tag checkov_id:            'CKV_AWS_238'
  tag checkov_category:      'GENERAL_SECURITY'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_guardduty_detector]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/guardduty_detector#enable'
  tag nist:                  ['SI-4', 'RA-5']
  tag nist_r4:               ['SI-4', 'RA-5']
  tag cci:                   ['CCI-002664']
  tag ksi:                   ['KSI-MLA-OSM']
  tag severity:              'medium'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  assets = aws_api_assets(type: 'aws_guardduty_detector', regions: scan_regions)

  # A region — or a whole service — that could not be READ is not the same as
  # one with nothing in it. A missing SDK gem, a denied call or an unreachable
  # endpoint all end up here, and without this assertion they render as "no
  # assets" and the control reports Not Applicable: the worst case reported as
  # "does not apply here".
  unreadable = assets.unreadable_regions
  unless unreadable.empty?
    describe "aws_guardduty_detector enumeration" do
      it 'read every region it attempted' do
        expect(unreadable.map { |r| "#{r[:region]}: #{r[:error]}" }).to be_empty
      end
    end
  end

  # A child list call that failed took a whole SUBTREE with it. That is not
  # "this parent had nothing", and it must never render as one: it is reported
  # per parent here, and it keeps the control APPLICABLE below so that only_if
  # cannot turn a broken enumeration into "does not apply here".
  parent_failures = assets.parent_failures
  unless parent_failures.empty?
    describe "aws_guardduty_detector enumeration" do
      it 'read the children of every parent it enumerated' do
        expect(parent_failures.map { |f| "#{f[:region]}/#{f[:parent_id]}: #{f[:error]}" }).to be_empty
      end
    end
  end

  # A field the API did not return is nil, and nil is not a failing value:
  # the asset does not express this setting, so it is out of scope for this
  # check rather than in breach of it.
  in_scope = assets.assets(exempt: exempt)
                   .reject { |a| a[:status].nil? }

  # `!unreadable.empty?` is load-bearing, and its absence was the bug this line
  # was written to prevent. InSpec's only_if does not merely mark the control
  # skipped: Inspec::Rule.prepare_checks DISCARDS every check and substitutes a
  # single no-op, so the enumeration assertion above never runs. A denied
  # ListX in every region therefore produced zero assets, zero assertions,
  # impact 0.0 and a "skipped" result — which HDF rolls up as Not Applicable.
  # The single most likely real failure of this profile reported as "this rule
  # does not apply here". Same reasoning as `unusable.positive?` in the stock
  # shape.
  applicable = !in_scope.empty? || !unreadable.empty? || !parent_failures.empty?
  impact 0.5
  impact 0.0 unless applicable
  only_if("no aws_guardduty_detector in scope expressing this setting "\
          "(#{assets.parents_seen} parent(s) enumerated by list_detectors)") { applicable }

  in_scope.each do |asset|
    describe "aws_guardduty_detector #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:status] }
      it { should eq 'ENABLED' }
    end
  end
end
